 26 | public ResponseEntity<Order> createOrder(@Valid @RequestBody OrderRequest request) {
 27 | Order order = new Order();
 28 | order.setId(null); // Force new ID generation
 29 | order.setUserId(request.getUserId());
 30 | order.setRestaurantId(request.getRestaurantId());
 31 | order.setDeliveryAddress(request.getDeliveryAddressAsString());
 32 | order.setStatus(OrderStatus.CREATED);
 33 | order.setCreatedAt(java.time.LocalDateTime.now());
