 35 | 
 36 | // Handle order items
 37 | if (request.getItems() != null) {
 38 | List<com.fooddelivery.order.entity.OrderItem> items = request.getItems().stream()
 39 | .map(itemReq -> {
 40 | com.fooddelivery.order.entity.OrderItem item = new com.fooddelivery.order.entity.OrderItem();
 41 | item.setId(null); // Force new ID generation
 42 | item.setMenuItemId(itemReq.getMenuItemId());
 43 | item.setQuantity(itemReq.getQuantity());
 44 | item.setPrice(itemReq.getPrice());
 45 | item.setOrder(order);
 46 | return item;
 47 | })
 48 | .collect(Collectors.toList());
 49 | order.setOrderItems(items);
 50 | }
 51 | 
 52 | // Calculate total if not provided
 53 | if (order.getTotalAmount() == null && order.getOrderItems() != null) {
 54 | java.math.BigDecimal total = order.getOrderItems().stream()
 55 | .map(i -> i.getPrice().multiply(java.math.BigDecimal.valueOf(i.getQuantity())))
 56 | .reduce(java.math.BigDecimal.ZERO, java.math.BigDecimal::add);
 57 | order.setTotalAmount(total);
 58 | }
 59 | 
 60 | Order saved = orderService.createOrderFromEntity(order);
 61 | return ResponseEntity.status(HttpStatus.CREATED).body(saved);
