 103 | @PathVariable("id") Long id,
 104 | @RequestBody Order orderRequest) {
 105 | return orderService.findById(id)
 106 | .map(existingOrder -> {
 107 | // Preserve created_at from existing record
 108 | orderRequest.setId(id);
 109 | orderRequest.setCreatedAt(existingOrder.getCreatedAt());
 110 | orderRequest.setUpdatedAt(java.time.LocalDateTime.now());
 111 | 
 112 | // Preserve items relationship
 113 | if (orderRequest.getOrderItems() != null) {
 114 | for (com.fooddelivery.order.entity.OrderItem item : orderRequest.getOrderItems()) {
 115 | item.setOrder(orderRequest);
 116 | }
 117 | } else {
 118 | orderRequest.setOrderItems(existingOrder.getOrderItems());
 119 | }
 120 | 
 121 | Order updated = orderService.save(orderRequest);
 122 | return ResponseEntity.ok(updated);
 123 | })
 124 | .orElse(ResponseEntity.notFound().build());
