 /**
 * Covers line 37 FALSE path: if (request.getItems() != null) - when items is NULL
 * AND line 53 FALSE path: if (order.getTotalAmount() == null && order.getOrderItems() != null)
 * When items=null, orderItems will be null, so the condition is false and total calculation is skipped.
 */
 @Test
 void createOrder_NullItems_ShouldCreate() throws Exception {
 // Create OrderRequest with ALL required fields but items=null
 OrderRequest request = new OrderRequest();
 request.setUserId(100L);
 request.setRestaurantId(200L);
 request.setDeliveryAddress("123 Main St, City, State 12345");
 // items is NOT set, so it will be null

 // Mock the service to return a valid order
 Order savedOrder = new Order();
 savedOrder.setId(1L);
 savedOrder.setUserId(100L);
 savedOrder.setRestaurantId(200L);
 savedOrder.setDeliveryAddress("123 Main St, City, State 12345");
 savedOrder.setStatus(OrderStatus.CREATED);
 savedOrder.setOrderItems(null); // No items
 savedOrder.setTotalAmount(null); // No total
 savedOrder.setCreatedAt(LocalDateTime.now());
 savedOrder.setUpdatedAt(LocalDateTime.now());

 when(orderService.createOrderFromEntity(any(Order.class))).thenReturn(savedOrder);

 // POST to /api/orders
 mockMvc.perform(post("/api/orders")
 .contentType(MediaType.APPLICATION_JSON)
 .content(objectMapper.writeValueAsString(request)))
 .andExpect(status().isCreated())
 .andExpect(jsonPath("$.id").value(1))
 .andExpect(jsonPath("$.userId").value(100));

 // Verify that createOrderFromEntity was called
 verify(orderService, times(1)).createOrderFromEntity(any(Order.class));
 }


