import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

/**
 * Brand new test file to cover missed branches in OrderController.
 * This file ONLY contains tests for branches that were not covered by OrderControllerTest.java.
 */
@WebMvcTest(OrderController.class)
class OrderControllerBranchTest {

 @Autowired
 private MockMvc mockMvc;

 @MockBean
 private OrderService orderService;

 @Autowired
 private ObjectMapper objectMapper;

 private Order testOrder;

 @BeforeEach
 void setUp() {
 testOrder = new Order();
 testOrder.setId(1L);
 testOrder.setUserId(100L);
 testOrder.setRestaurantId(200L);
 testOrder.setDeliveryAddress("123 Main St, City, State 12345");
 testOrder.setStatus(OrderStatus.CREATED);
 testOrder.setTotalAmount(BigDecimal.valueOf(25.50));
 testOrder.setCreatedAt(LocalDateTime.now());
 testOrder.setUpdatedAt(LocalDateTime.now());
 }

 /**
 * Covers line 53 TRUE path: if (order.getTotalAmount() == null && order.getOrderItems() != null)
 * When totalAmount is null AND items exist, the total is calculated from items.
 * This also covers lines 54-57: the lambda that calculates total.
 */
 @Test
 void createOrder_NullTotalWithItems_ShouldCalculateTotal() throws Exception {
 // Create OrderRequest with items but NO totalAmount
 OrderRequest request = new OrderRequest();
 request.setUserId(100L);
 request.setRestaurantId(200L);
 request.setDeliveryAddress("123 Main St, City, State 12345");

 // Add items - total will be calculated
 OrderItemRequest item = new OrderItemRequest();
 item.setMenuItemId(1L);
 item.setQuantity(2);
 item.setPrice(BigDecimal.valueOf(12.50));
 request.setItems(List.of(item));

 // Mock the service to return an order with calculated total
 Order savedOrder = new Order();
 savedOrder.setId(1L);
 savedOrder.setUserId(100L);
 savedOrder.setRestaurantId(200L);
 savedOrder.setDeliveryAddress("123 Main St, City, State 12345");
 savedOrder.setStatus(OrderStatus.CREATED);
 savedOrder.setTotalAmount(BigDecimal.valueOf(25.00)); // Calculated: 2 * 12.50
 savedOrder.setCreatedAt(LocalDateTime.now());
 savedOrder.setUpdatedAt(LocalDateTime.now());

 when(orderService.createOrderFromEntity(any(Order.class))).thenReturn(savedOrder);

 // POST to /api/orders
 mockMvc.perform(post("/api/orders")
 .contentType(MediaType.APPLICATION_JSON)
 .content(objectMapper.writeValueAsString(request)))
 .andExpect(status().isCreated())
 .andExpect(jsonPath("$.id").value(1))
 .andExpect(jsonPath("$.userId").value(100));

 // Verify that createOrderFromEntity was called
 verify(orderService, times(1)).createOrderFromEntity(any(Order.class));
 }

 /**
 * Covers line 53 FALSE path: if (order.getTotalAmount() == null && order.getOrderItems() != null)
 * When totalAmount is already set, calculation is skipped.
 */
 @Test
 void createOrder_WithTotalAmountSet_ShouldNotRecalculate() throws Exception {
 // Create OrderRequest with items AND totalAmount already set
 // This covers line 53 FALSE path: totalAmount != null, so calculation is skipped
 OrderRequest request = new OrderRequest();
 request.setUserId(100L);
 request.setRestaurantId(200L);
 request.setDeliveryAddress("123 Main St, City, State 12345");

 // Add items
 OrderItemRequest item = new OrderItemRequest();
 item.setMenuItemId(1L);
 item.setQuantity(2);
 item.setPrice(BigDecimal.valueOf(12.50));
 request.setItems(List.of(item));

 // Mock the service to return an order with totalAmount already set
 Order savedOrder = new Order();
 savedOrder.setId(1L);
 savedOrder.setUserId(100L);
 savedOrder.setRestaurantId(200L);
 savedOrder.setDeliveryAddress("123 Main St, City, State 12345");
 savedOrder.setStatus(OrderStatus.CREATED);
 savedOrder.setTotalAmount(BigDecimal.valueOf(50.00)); // Total already set
 savedOrder.setCreatedAt(LocalDateTime.now());
 savedOrder.setUpdatedAt(LocalDateTime.now());

 when(orderService.createOrderFromEntity(any(Order.class))).thenReturn(savedOrder);

 // POST to /api/orders
 mockMvc.perform(post("/api/orders")
 .contentType(MediaType.APPLICATION_JSON)
 .content(objectMapper.writeValueAsString(request)))
 .andExpect(status().isCreated())
 .andExpect(jsonPath("$.id").value(1))
 .andExpect(jsonPath("$.userId").value(100));

 // Verify that createOrderFromEntity was called
 verify(orderService, times(1)).createOrderFromEntity(any(Order.class));
 }

 /**
 * Covers lines 105-124 orElse: updateOrder when order ID does not exist
 * When findById returns Optional.empty(), the orElse branch returns 404 Not Found.
 */
 @Test
 void updateOrder_NotFound() throws Exception {
 // Mock findById to return empty
 when(orderService.findById(999L)).thenReturn(Optional.empty());

 // Create a valid order request
 Order request = new Order();
 request.setUserId(100L);
 request.setRestaurantId(200L);
 request.setDeliveryAddress("123 Main St");
 request.setStatus(OrderStatus.CREATED);
 request.setTotalAmount(BigDecimal.valueOf(10.00));

 // PUT to /api/orders/999
 mockMvc.perform(put("/api/orders/999")
 .contentType(MediaType.APPLICATION_JSON)
 .content(objectMapper.writeValueAsString(request)))
 .andExpect(status().isNotFound());

 // Verify findById was called
 verify(orderService, times(1)).findById(999L);
 // Verify save was NEVER called
 verify(orderService, never()).save(any(Order.class));
 }

 /**
 * Covers lines 113-118 FALSE path: if (orderRequest.getOrderItems() != null)
 * When orderItems is null, the else branch copies existing order items.
 */
 @Test
 void updateOrder_NullItems_CopiesExisting() throws Exception {
 // Create existing order with items
 Order existingOrder = new Order();
 existingOrder.setId(1L);
 existingOrder.setCreatedAt(LocalDateTime.now());

 OrderItem existingItem = new OrderItem();
 existingItem.setId(10L);
 existingItem.setMenuItemId(5L);
 existingItem.setQuantity(2);
 existingItem.setPrice(BigDecimal.valueOf(12.50));
 existingItem.setOrder(existingOrder);

 List<OrderItem> existingItems = new ArrayList<>();
 existingItems.add(existingItem);
 existingOrder.setOrderItems(existingItems);

 when(orderService.findById(1L)).thenReturn(Optional.of(existingOrder));

 // Create request WITHOUT orderItems (null)
 Order request = new Order();
 request.setUserId(100L);
 request.setRestaurantId(200L);
 request.setDeliveryAddress("123 Main St");
 request.setStatus(OrderStatus.CREATED);
 request.setTotalAmount(BigDecimal.valueOf(10.00));
 // orderItems is NOT set, so it will be null

 // Mock save to return the request
 when(orderService.save(any(Order.class))).thenReturn(request);

 // PUT to /api/orders/1
 mockMvc.perform(put("/api/orders/1")
