 .andExpect(status().isOk());

 // Verify findById and save were called
 verify(orderService, times(1)).findById(1L);
 verify(orderService, times(1)).save(any(Order.class));
 }

 /**
 * Covers lines 113-118 TRUE path: if (orderRequest.getOrderItems() != null)
 * When orderItems is not null, the if branch sets the order reference for each item.
 */
 @Test
 void updateOrder_WithItems_SetsReference() throws Exception {
 // Create existing order
 Order existingOrder = new Order();
 existingOrder.setId(1L);
 existingOrder.setCreatedAt(LocalDateTime.now());
 existingOrder.setOrderItems(new ArrayList<>());

 when(orderService.findById(1L)).thenReturn(Optional.of(existingOrder));

 // Create request WITH orderItems
 Order request = new Order();
 request.setUserId(100L);
