&lt;line nr="54" mi="4" ci="0" mb="0" cb="0"/&gt; &lt;!-- 4 missed instructions --&gt;
&lt;line nr="55" mi="12" ci="0" mb="0" cb="0"/&gt; &lt;!-- 12 missed instructions (lambda) --&gt;
