 );

 // Use reflection to call private method
 BigDecimal total = ReflectionTestUtils.invokeMethod(
 controller, "calculateOrderTotal", items
 );

 assertEquals(BigDecimal.valueOf(35), total); // 2*10 + 3*5 = 35
}
```

